#include <bits/stdc++.h>
using namespace std;
int main() {
	cin.tie(nullptr);
	ios::sync_with_stdio(false);
	int n;
	long long m;
	cin >> n >> m;
	vector<int> a(n);
	for (int &v : a)
		cin >> v;
	vector<vector<int>> g(11);
	for (int v : a)
		g[to_string(v).size()].push_back(v % m);
	for (auto &gg : g)
		sort(gg.begin(), gg.end());
	long long ans = 0;
	for (long long ai : a) {
		for (int k = 1; k < 11; k++) {
			ai *= 10, ai %= m;
			const int key = (m - ai) % m;
			ans += lower_bound(g[k].begin(), g[k].end(), key + 1) - lower_bound(g[k].begin(), g[k].end(), key);
		}
	}
	cout << ans << endl;
}
